{
  "category_edits": [
    {
      "category": "training_strategy",
      "rationale": "Replace validation-driven learning-rate reductions with five epochs of linear warmup, followed by cosine decay to 10% of the existing peak learning rate at epoch 200. This may stabilize validation performance while preserving the optimizer, early stopping, architecture, loss, and all four dataset models.",
      "edits": [
        {
          "find": "    scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(\n        optimizer, mode=\"max\", factor=0.5, patience=1,\n        threshold=0.0, threshold_mode=\"abs\", min_lr=LR * 0.125\n    )",
          "replace": "    def learning_rate_for_epoch(epoch: int) -> float:\n        if epoch <= 5:\n            return LR * epoch / 5.0\n        progress = min(max((epoch - 5) / 195.0, 0.0), 1.0)\n        return LR * (0.1 + 0.9 * 0.5 * (1.0 + math.cos(math.pi * progress)))"
        },
        {
          "find": "    for epoch in range(1, NUM_EPOCHS + 1):\n        model.train()",
          "replace": "    for epoch in range(1, NUM_EPOCHS + 1):\n        for param_group in optimizer.param_groups:\n            param_group[\"lr\"] = learning_rate_for_epoch(epoch)\n        model.train()"
        },
        {
          "find": "            scheduler.step(hr10)\n",
          "replace": ""
        }
      ]
    }
  ],
  "change_summary": "Apply five-epoch linear warmup and cosine learning-rate decay through epoch 200 to each category's single GRU model. All other training and prediction behavior remains unchanged."
}
